// Loads the catalog (copied from the app) and the seed tables (generated by
// tool/gen_seeds.dart).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export interface CatalogItem {
  id: string;
  kind: 'ball' | 'map';
  price: 'free' | 'coins' | 'paid';
  coins?: number;
  productId?: string;
  shape?: string;
}

export interface Catalog {
  removeAds: { productId: string };
  coinPacks: { productId: string; coins: number }[];
  items: CatalogItem[];
  bet: { minCoins: number; maxCoins: number };
}

export interface ShapeTable {
  multipliers: number[];
  /** [seed, attempt the ball escapes on] */
  seeds: [number, number][];
}

export interface SeedTables {
  rtp: number;
  /** [first, last] attempt of each guess band, inclusive. */
  bands: [number, number][];
  shapes: Record<string, ShapeTable>;
}

const dataDir = join(__dirname, '..', 'data');

export function loadCatalog(): Catalog {
  return JSON.parse(readFileSync(join(dataDir, 'catalog.json'), 'utf8')) as Catalog;
}

export function loadSeedTables(): SeedTables {
  return JSON.parse(readFileSync(join(dataDir, 'seeds.json'), 'utf8')) as SeedTables;
}
